def _sort_taint_edges_inplace(graph: nx.DiGraph) -> None:
    te = graph.graph.get("taint_edges")
    if not te:
        return

    def _key(e: Any) -> tuple[str, int, str, str]:
        if hasattr(e, "scope"):
            return (
                str(e.scope),
                int(e.line or 0),
                str(e.source_node),
                str(e.sink_node),
            )
        if isinstance(e, dict):
            return (
                str(e.get("scope", "")),
                int(e.get("line") or 0),
                str(e.get("source_node", "")),
                str(e.get("sink_node", "")),
            )
        return ("", 0, "", "")

    te.sort(key=_key)

